	// MT2009_PLUS_QUEST_TIMER_RESCHEDULE_V1 (add): the same name and argument again (a quest's tick asking for its next
	// tick inside its own handler, or a stage/floor start while the previous tick still waits) reschedules it:
	// the waiting (or the running one-shot) event is cancelled and the new one is the registered one. The old
	// refusal left the new event running untracked - a second chain clear_server_timer / CancelServerTimers could
	// never stop, one more for every restart. Event flag m2_quest_timer_legacy = 1: the old refusal.
	itertype(m_mapServerTimer) itOld = m_mapServerTimer.find(make_pair(name, arg));
	if (itOld != m_mapServerTimer.end())
	{
		if (GetEventFlag("m2_quest_timer_legacy") != 0)
		{
			sys_err("already registered server timer name:%s arg:%u", name.c_str(), arg);
			return;
		}
		LPEVENT old = itOld->second;
		const bool self = old && old->is_processing;
		if (old && old != event)
			event_cancel(&old);
		itOld->second = event;
		static DWORD s_dwSelf = 0, s_dwOther = 0, s_dwLogAt = 0;
		if (self)
			++s_dwSelf;
		else
			++s_dwOther;
		const DWORD dwNow = get_dword_time();
		if (s_dwLogAt == 0 || dwNow - s_dwLogAt >= 600000)
		{
			sys_log(0, "QUEST_TIMER: rescheduled own_handler=%u while_waiting=%u last=%s:%u", s_dwSelf, s_dwOther, name.c_str(), arg);
			s_dwSelf = s_dwOther = 0;
			s_dwLogAt = dwNow;
		}
		return;
	}
	m_mapServerTimer.emplace(make_pair(name, arg), event);
}

void CQuestManager::ClearServerTimerNotCancel(const std::string& name, DWORD arg, LPEVENT self)
{
	// MT2009_PLUS_QUEST_TIMER_RESCHEDULE_V1 (clear): after a one-shot's handler - not the next tick it registered
	itertype(m_mapServerTimer) it = m_mapServerTimer.find(make_pair(name, arg));
	if (it != m_mapServerTimer.end() && (!self || it->second == self))
		m_mapServerTimer.erase(it);
}

